const weeklySlice = createSlice({
    name: "week",
    initialState: {
      data: {},
      loading: false,
    },
    reducers: {
      getWeeklyWeather(state, action) {
        return (state = action.payload);
      },
    },
    selectors: {
      getWeeklyWeather: (state) => state,
    },
    extraReducers: (builder) => {
      builder.addCase(fetchTodaysWeather.fulfilled, (state, action) => {
        state.data = action.payload;
        state.loading = false;
        console.log(state.loading);
      });
      builder.addCase(fetchTodaysWeather.pending, (state) => {
        state.loading = true;
        console.log(state.loading);
      });
      builder.addCase(fetchWeeklyWeather.fulfilled, (state, action) => {
        state.data = action.payload;

        console.log(state.loading);
        state.loading = false;
      });
      builder.addCase(fetchWeeklyWeather.pending, (state) => {
        console.log(state.loading);
        state.loading = true;
      });
    },
  });

  export const weeklyReducer = weeklySlice.reducer;
  export const { getTodaysWeather, getWeeklyWeather } = weatherSlice.selectors;
